'use strict';

/**
* Compute the arithmetic mean of a one-dimensional double-precision floating-point ndarray using Welford's algorithm.
*
* @module @stdlib/stats/base/ndarray/dmeanwd
*
* @example
* import Float64Vector from '@stdlib/ndarray/vector/float64';
* import dmeanwd from '@stdlib/stats/base/ndarray/dmeanwd';
*
* var x = new Float64Vector( [ 1.0, 3.0, 4.0, 2.0 ] );
*
* var v = dmeanwd( [ x ] );
* // returns 2.5
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var dmeanwd;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dmeanwd = main;
} else {
	dmeanwd = tmp;
}


// EXPORTS //

export default dmeanwd;
