'use strict';

/**
* Compute the minimum absolute value of a one-dimensional single-precision floating-point ndarray.
*
* @module @stdlib/stats/base/ndarray/sminabs
*
* @example
* import Float32Vector from '@stdlib/ndarray/vector/float32';
* import sminabs from '@stdlib/stats/base/ndarray/sminabs';
*
* var x = new Float32Vector( [ -1.0, 3.0, -4.0, 2.0 ] );
*
* var v = sminabs( [ x ] );
* // returns 1.0
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var sminabs;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	sminabs = main;
} else {
	sminabs = tmp;
}


// EXPORTS //

export default sminabs;
